import AVFoundation
import AppKit

/// The grants a screen recording stands on — each grant's read, the step a
/// press takes, the pane URLs and the sentences — values a probe can call.
/// A pure move out of `RecordingSetup.swift` under road map "creator-jobs"
/// CU0a's toll U1; `RecordingSetup+Camera.swift` extends `RecordingGrant`
/// with the camera's grant.

// MARK: - The grants

/// Decision 4 (road map 3 §0): the PANEL asks for the grants, the tool never
/// does — the rule the speech grant's `canAsk` carried, for two grants.
/// What lives here is the READ of each grant, the STEP a press takes, the
/// pane URLs and the sentences — all pure: nothing here prompts or opens;
/// `CGRequestScreenCaptureAccess()`, `AVCaptureDevice.requestAccess` and
/// the pane's `NSWorkspace.open` are called by the recorder panel alone
/// (`RecorderPanelController+Grants.swift`), because a system prompt needs
/// a person in front of it. A press asks for Screen Recording ONCE and
/// opens the pane on every later press (spec §11 recording) — but only in
/// a launchd-owned launch: a shell-launched press always asks, because TCC
/// gives that prompt to the terminal (R0 q1). A denied or restricted
/// microphone opens its pane; `.notDetermined` asks.
///
/// **Both refusal sentences are COMPUTED, and end with `launchClause` when
/// it is non-empty** (R1 review, unjudged and upheld): R0 q1 measured that
/// a shell-launched Frame Job is attributed by TCC to the TERMINAL, so a
/// person who followed the pane sentence and granted Frame Job.app would have
/// granted the wrong application and be refused again with no way to tell
/// why. The pane sentence stays the PREFIX — `recording_proof.py` matches
/// on it — and the clause names the launching process's pid.
enum RecordingGrant {
    /// `CGPreflightScreenCaptureAccess()` — true when this PROCESS may
    /// capture. R0 q1: a shell-launched binary is attributed by TCC to the
    /// terminal, so from a proof this reads the terminal's grant, not the
    /// app's.
    static var screenRecordingGranted: Bool { CGPreflightScreenCaptureAccess() }

    /// The pane sentence alone — the prefix of `screenRecordingRefusal`.
    static let screenRecordingPaneSentence =
        "Screen Recording is not granted to Frame Job. Turn it on in System Settings ▸ "
        + "Privacy & Security ▸ Screen & System Audio Recording, then relaunch."

    static var screenRecordingRefusal: String { screenRecordingPaneSentence + launchClause }

    /// Empty for an app launched by launchd (`open -a`, the Finder, the
    /// Dock — ppid 1, responsible for itself); otherwise the sentence that
    /// says whose grant this process is actually running under. `getppid()`
    /// is the cheapest true reading: R0 q1's `responsibility_get_pid_
    /// responsible_for_pid` is private API, and the parent is what TCC
    /// follows for a process launched from a shell.
    static var launchClause: String {
        let parent = getppid()
        guard parent != 1 else { return "" }
        return " This Frame Job was launched by another process (pid \(parent)), so the grant "
            + "that counts is that application's — the terminal's, for a shell launch; or "
            + "relaunch with open -a \"Frame Job\"."
    }

    /// `AVCaptureDevice.authorizationStatus(for: .audio)`. Read BEFORE any
    /// `AVCaptureDeviceInput` is made: that initializer auto-prompts on
    /// `.notDetermined`, which is exactly the prompt the tool may not put up.
    static var microphoneStatus: AVAuthorizationStatus {
        AVCaptureDevice.authorizationStatus(for: .audio)
    }

    /// The status as the framework spells it, for a message a script can
    /// read — `Transcriber.name(of:)`'s shape.
    static func name(of status: AVAuthorizationStatus) -> String {
        switch status {
        case .notDetermined: return "notDetermined"
        case .restricted: return "restricted"
        case .denied: return "denied"
        case .authorized: return "authorized"
        @unknown default: return "unknown"
        }
    }

    /// Names the status word and the one action that changes it: a
    /// `notDetermined` grant is asked for by pressing Record in the panel (the
    /// only place that may prompt), a denied or restricted one is turned on
    /// in System Settings. `launchClause` follows, on the same terms as the
    /// screen sentence's.
    static func microphoneRefusal(_ status: AVAuthorizationStatus) -> String {
        let head = "The microphone is not granted to Frame Job (status: \(name(of: status))). "
        switch status {
        case .notDetermined:
            return head + "Press Record in File ▸ New Recording… once to grant it." + launchClause
        default:
            return head + "Turn it on in System Settings ▸ Privacy & Security ▸ Microphone, "
                + "then relaunch." + launchClause
        }
    }

    // MARK: The step a press takes

    /// What a press of Record does about one grant: go on, put up the
    /// system prompt, or open System Settings at the grant's pane.
    enum Step: Equatable {
        case proceed
        case ask
        case openPane
    }

    /// True when launchd is the parent (`open -a`, the Finder, the Dock) —
    /// the reading `launchClause` makes, so the two cannot disagree.
    static var launchedByLaunchd: Bool { getppid() == 1 }

    /// Screen Recording: granted goes on; a shell launch always asks (its
    /// prompt is the terminal's, R0 q1, so `asked` means nothing there);
    /// a launchd-owned press that has asked before opens the pane; else ask.
    static func screenStep(granted: Bool, asked: Bool, launchedByLaunchd: Bool) -> Step {
        if granted { return .proceed }
        if !launchedByLaunchd { return .ask }
        if asked { return .openPane }
        return .ask
    }

    /// The microphone, when one is chosen: authorized goes on,
    /// `.notDetermined` asks, and denied, restricted or unknown opens the
    /// pane — the system never prompts twice for it.
    static func microphoneStep(_ status: AVAuthorizationStatus) -> Step {
        switch status {
        case .authorized: return .proceed
        case .notDetermined: return .ask
        case .denied, .restricted: return .openPane
        @unknown default: return .openPane
        }
    }

    /// System Settings ▸ Privacy & Security ▸ Screen & System Audio Recording.
    static let screenRecordingPaneURL = URL(
        string: "x-apple.systempreferences:com.apple.preference.security?Privacy_ScreenCapture")

    /// System Settings ▸ Privacy & Security ▸ Microphone.
    static let microphonePaneURL = URL(
        string: "x-apple.systempreferences:com.apple.preference.security?Privacy_Microphone")

    /// System Settings ▸ Privacy & Security ▸ Camera (camera-recording CR1c).
    static let cameraPaneURL = URL(
        string: "x-apple.systempreferences:com.apple.preference.security?Privacy_Camera")

    /// What a note adds once the pane has been opened.
    static let paneOpenedSentence = " System Settings is open at that pane."

    /// The screen note after the pane opened: the pane sentence stays the
    /// PREFIX, and `launchClause` stays last.
    static var screenRecordingOpenedNote: String {
        screenRecordingPaneSentence + paneOpenedSentence + launchClause
    }

    /// The microphone note after its pane opened: the refusal's head and
    /// fix, the opened sentence, then `launchClause`.
    static func microphoneOpenedNote(_ status: AVAuthorizationStatus) -> String {
        "The microphone is not granted to Frame Job (status: \(name(of: status))). "
            + "Turn it on in System Settings ▸ Privacy & Security ▸ Microphone, then relaunch."
            + paneOpenedSentence + launchClause
    }

    // MARK: Input Monitoring (road map creator-jobs CU6, spec §11 CU-3, CU-62)

    /// `CGPreflightListenEventAccess()` — whether this process may listen to key-downs (CU-S1
    /// `grant_api=cg`). A shell launch reads the terminal's grant, as Screen Recording does.
    static var inputMonitoringGranted: Bool { CGPreflightListenEventAccess() }

    /// CU-3's sentence: no "then relaunch" (CU0b measured none is needed).
    static let inputMonitoringPaneSentence =
        "Input Monitoring is not granted to Frame Job. Turn it on in System Settings ▸ "
        + "Privacy & Security ▸ Input Monitoring."

    /// `record_screen`'s and the recorder's refusal: the pane sentence, then `launchClause`.
    static var inputMonitoringRefusal: String { inputMonitoringPaneSentence + launchClause }

    /// What the panel's note adds: no prompt shows and Frame Job is not listed until a person
    /// adds it (CU0b, the owner's JOB-29 run).
    static let inputMonitoringAddSentence = " If Frame Job is not in its list, add it with +."

    /// The panel's note after a press: the pane sentence, the add sentence, the opened sentence
    /// when System Settings opened, then `launchClause`.
    static func inputMonitoringNote(opened: Bool) -> String {
        inputMonitoringPaneSentence + inputMonitoringAddSentence
            + (opened ? paneOpenedSentence : "") + launchClause
    }

    /// Input Monitoring: `screenStep`'s table — granted goes on; a shell launch always asks; a
    /// launchd-owned press that has asked before opens the pane; else ask (CU-62).
    static func inputMonitoringStep(granted: Bool, asked: Bool, launchedByLaunchd: Bool) -> Step {
        if granted { return .proceed }
        if !launchedByLaunchd { return .ask }
        if asked { return .openPane }
        return .ask
    }

    /// System Settings ▸ Privacy & Security ▸ Input Monitoring.
    static let inputMonitoringPaneURL = URL(
        string: "x-apple.systempreferences:com.apple.preference.security?Privacy_ListenEvent")
}

            },
            inputMonitoringGranted: { RecordingGrant.inputMonitoringGranted },
            requestInputMonitoring: { _ = CGRequestListenEventAccess() },
            inputMonitoringAsked: { UserDefaults.standard.bool(forKey: inputMonitoringAskedKey) },
            rememberInputMonitoringAsked: {
                UserDefaults.standard.set(true, forKey: inputMonitoringAskedKey)
            })
    }
}

/// The grants, for the recorder panel (road map 3, R1c; spec §11
/// recording) — `RecorderPanelController.swift`'s seventh file, cut out of
/// `+Recording.swift` when the press learned to open System Settings.
///
/// **The grants are asked for HERE and nowhere else, and UNCONDITIONALLY**
/// (decision 4: the TOOL never asks — it reads the status and refuses by
/// name — because a system prompt needs a person in front of it; the panel
/// asks, because a press of Record IS that person, exactly as the transcribe
/// sheet's Start is). **This is also the only place System Settings is
/// opened for them**, and the tool never opens it. Screen Recording is
/// asked with `CGRequestScreenCaptureAccess()` on the FIRST press that finds
/// it absent — the system prompt appears once per app, not per launch — and
/// the ask is remembered in `FrameJobScreenRecordingAsked`; every later press
/// opens the Screen & System Audio Recording pane and the note says so.
/// `CGRequestScreenCaptureAccess()` returns false at once on a first ask, so
/// the refusal sentence is shown either way and the person presses Record
/// again once the grant is on. The flag is read and written only in a
/// launchd-owned launch: a shell-launched press always asks and never
/// remembers, because TCC attributes that prompt to the terminal (R0 q1).
/// The microphone is asked only when one is chosen, from `.notDetermined`,
/// and the countdown starts from the answer; `.denied` and `.restricted`
/// open the Microphone pane and stop there, and a prompt's answer never
/// opens it. Both readings happen BEFORE the countdown, so a countdown never
/// ends in a prompt. An earlier draft gated both asks on a `canAsk` (since
/// deleted with the speech grant) — false for a scripted agent launch —
/// and the R1 review measured what that cost: under that flag the refusal
/// note told the person to press the button they had just pressed, and a
/// `notDetermined` microphone could never be granted from anywhere.
/// `canAsk` is the tool's rule about a prompt nobody would see; it does not
/// apply to a button somebody clicked. **The Camera grant** (CR1c, spec §11
/// CAM-5) is the third, read only for Source Camera, whose press never reads
/// Screen Recording: the microphone's steps, through its own pane
/// (`Privacy_Camera`), and its prompt's answer RE-READS the grant before the
/// microphone and the countdown, so a refused prompt stops there. **Input
/// Monitoring** (road map creator-jobs CU6, spec §11 CU-3, CU-62) is the
/// fourth, read only when Record shortcuts is on with a screen source, after
/// Screen Recording and before the Camera and the Microphone. Its step is
/// Screen Recording's table, remembered in `FrameJobInputMonitoringAsked`;
/// because no prompt shows and Frame Job is not listed until a person adds
/// it (CU0b), an ask ALSO opens the Input Monitoring pane, and the note says
/// to add Frame Job with + (`inputMonitoringNote(opened:)`).
extension RecorderPanelController {
    /// The doors every grant call goes through; a probe replaces it.
    static var grantDoors = RecorderGrantDoors.live

    /// A system prompt, or System Settings, is about to come up in ANOTHER
    /// process at normal window level, and a `.floating` panel sits over
    /// every normal window on the screen: the person found the Screen
    /// Recording prompt hidden behind the panel until they dragged it away
    /// (2026-09-28). So the panel steps down to `.normal` first, and
    /// `floatAgain` puts it back on the next press that goes on, or on
    /// `show()`.
    func stepAsideForSystemUI() { window?.level = .normal }
    func floatAgain() { window?.level = .floating }

    /// Screen Recording, for a press: true to go on; false with the note
    /// set, and the press ends. `screenStep` is the one decision point.
    func checkScreenRecordingGrant() -> Bool {
        floatAgain()
        let doors = Self.grantDoors
        let owned = doors.launchedByLaunchd()
        let step = RecordingGrant.screenStep(
            granted: doors.screenGranted(), asked: doors.screenAsked(), launchedByLaunchd: owned)
        switch step {
        case .proceed:
            return true
        case .ask:
            if owned { doors.rememberScreenAsked() }
            stepAsideForSystemUI()
            doors.requestScreen()
            setNote(RecordingGrant.screenRecordingRefusal)
            return false
        case .openPane:
            stepAsideForSystemUI()
            let opened = RecordingGrant.screenRecordingPaneURL.map(doors.openSettings) ?? false
            setNote(
                opened ? RecordingGrant.screenRecordingOpenedNote : RecordingGrant.screenRecordingRefusal)
            return false
        }
    }

    /// Input Monitoring, for a press (CU-62): true to go on — Record shortcuts
    /// off (it is `.off` for a voice-over and a camera) or granted; false with
    /// the note set, and the press ends. `inputMonitoringStep` decides.
    func checkInputMonitoringGrant() -> Bool {
        guard currentChoice().keys == .shortcuts else { return true }
        floatAgain()
        let doors = Self.grantDoors
        let owned = doors.launchedByLaunchd()
        let step = RecordingGrant.inputMonitoringStep(
            granted: doors.inputMonitoringGranted(), asked: doors.inputMonitoringAsked(),
            launchedByLaunchd: owned)
        switch step {
        case .proceed:
            return true
        case .ask:
            if owned { doors.rememberInputMonitoringAsked() }
            stepAsideForSystemUI()
            doors.requestInputMonitoring()
            let opened = RecordingGrant.inputMonitoringPaneURL.map(doors.openSettings) ?? false
            setNote(RecordingGrant.inputMonitoringNote(opened: opened))
            return false
        case .openPane:
            stepAsideForSystemUI()
            let opened = RecordingGrant.inputMonitoringPaneURL.map(doors.openSettings) ?? false
            setNote(RecordingGrant.inputMonitoringNote(opened: opened))
            return false
        }
    }

    /// The microphone, for a press: true to go on (none chosen, or
    /// authorized); false when it asked (the answer continues the press) or
    /// opened its pane.
    func checkMicrophoneGrant() -> Bool {
        guard currentChoice().microphone != nil else { return true }
        let doors = Self.grantDoors
        let status = doors.microphoneStatus()
        switch RecordingGrant.microphoneStep(status) {
        case .proceed:
            return true
        case .ask:
            recordButton.isEnabled = false
            stepAsideForSystemUI()
            doors.requestMicrophone { [weak self] in self?.microphoneAnswered() }
            return false
        case .openPane:
            stepAsideForSystemUI()
            let opened = RecordingGrant.microphonePaneURL.map(doors.openSettings) ?? false
            setNote(
                opened
                    ? RecordingGrant.microphoneOpenedNote(status)
                    : RecordingGrant.microphoneRefusal(status))
            return false
        }
    }

    /// The prompt's answer. The button comes back either way; the countdown
    /// begins only in an idle panel that is still ON SCREEN (R1 review) — a
    /// panel closed during the prompt must not count down where nobody can
    /// cancel it, and `panelWillClose` cannot cancel a countdown that has not
    /// begun. It never opens System Settings.
    private func microphoneAnswered() {
        recordButton.isEnabled = true
        guard phase == .idle, window?.isVisible == true else { return }
        let status = Self.grantDoors.microphoneStatus()
        guard status == .authorized else {
            setNote(RecordingGrant.microphoneRefusal(status))
            return
        }
        setNote("")
        floatAgain()
        beginCountdown()
    }

    /// The camera, for a press with Source Camera: true to go on
    /// (authorized); false when it asked (the answer continues the press) or
    /// opened its pane — `checkMicrophoneGrant`'s three arms.
    func checkCameraGrant() -> Bool {
        let doors = Self.grantDoors
        let status = doors.cameraStatus()
        switch RecordingGrant.cameraStep(status) {
        case .proceed:
            return true
        case .ask:
            recordButton.isEnabled = false
            stepAsideForSystemUI()
            doors.requestCamera { [weak self] in self?.cameraAnswered() }
            return false
        case .openPane:
            stepAsideForSystemUI()
            let opened = RecordingGrant.cameraPaneURL.map(doors.openSettings) ?? false
            setNote(
                opened
                    ? RecordingGrant.cameraOpenedNote(status)
                    : RecordingGrant.cameraRefusal(status))
            return false
        }
    }

    /// The camera prompt's answer, `microphoneAnswered`'s rule: the button
    /// comes back either way, and the press goes on only in an idle panel
    /// still on screen. The grant is READ AGAIN first — anything but
    /// authorized stops with the refusal, no microphone prompt and no
    /// countdown — then the microphone's grant, then the countdown.
    private func cameraAnswered() {
        recordButton.isEnabled = true
        guard phase == .idle, window?.isVisible == true else { return }
        let status = Self.grantDoors.cameraStatus()
        guard status == .authorized else {
            setNote(RecordingGrant.cameraRefusal(status))
            return
        }
        setNote("")
        floatAgain()
        guard checkMicrophoneGrant() else { return }
        beginCountdown()
    }
}

