    /// The arm ceiling, for the lookup half of an attempt: a stale number, a
    /// phase that moved on, or an attempt the recorder already holds (its
    /// own ceiling reports that one) does nothing. Internal so a probe can
    /// fire it without a lookup.
    func armTimedOut(generation: Int) {
        guard phase == .starting, generation == startGeneration, !launched else { return }
        startFailed(RecorderError.startTimedOut)
    }

    /// A Stop before the recorder was handed the attempt: the pending
    /// lookup's answer is orphaned by the generation bump, the prepared
    /// microphone let go, and the panel idle with a note saying nothing was
    /// recorded.
    private func abandonStart() {
        startGeneration += 1
        startTimer?.invalidate()
        startTimer = nil
        recorder.discardPreparedMicrophone()
        recorder.discardPreparedCamera()
        phase = .idle
        setNote(Self.abandonedSentence)
    /// then excludes nothing rather than crashing. A window source is the
    /// window alone. A `.picked` source carries the picker's filter and has
    /// none to build, a `.voiceOver` source has no picture at all, and a
    /// `.camera` source's picture is a camera's, not a screen's.
    static func filter(
        for source: RecordingSource, in content: SCShareableContent,
        excluding exclusion: RecordingExclusion
    ) throws -> SCContentFilter {
        switch source {
        case .display(let id):
            guard let display = content.displays.first(where: { $0.displayID == id }) else {
                throw RecorderError.startFailed(
                    "No display with id \(id) is shareable; the displays are "
                        + content.displays.map { "\($0.displayID)" }.joined(separator: ", ") + ".")
            }
            if !exclusion.bundleIDs.isEmpty {
                let apps = content.applications.filter {
                    exclusion.bundleIDs.contains($0.bundleIdentifier)
                }
                return SCContentFilter(
                    display: display, excludingApplications: apps, exceptingWindows: [])
            }
            let windows = content.windows.filter { exclusion.windowIDs.contains($0.windowID) }
            return SCContentFilter(display: display, excludingWindows: windows)
        case .window(let id):
            guard let window = content.windows.first(where: { $0.windowID == id }) else {
                throw RecorderError.startFailed("No window with id \(id) is shareable.")
            }
            return SCContentFilter(desktopIndependentWindow: window)
        case .picked:
            throw RecorderError.startFailed(
                "A picked source carries the picker's own filter; none can be built here.")
        case .voiceOver:
            throw RecorderError.startFailed(
                "A voice-over records the microphone alone; it has no filter to build.")
        case .camera:
            throw RecorderError.startFailed(
                "A camera recording records a camera; it has no filter to build.")
        }
    }

    /// The device a choice names, or nil for an id no connected microphone
    /// carries.
    static func microphone(withID id: String) -> AVCaptureDevice? {
        AVCaptureDevice.DiscoverySession(
            deviceTypes: [.microphone, .external], mediaType: .audio, position: .unspecified
    func recordingSource(
        _ displayIndex: Int, _ windowID: CGWindowID?, in content: SCShareableContent
    ) throws -> RecordingSource {
        if let windowID { return .window(windowID) }
        let displays = Self.orderedDisplays(content)
        guard !displays.isEmpty else {
            throw ToolError(
                message: "No display is shareable right now — the console is locked or every "
                    + "display is asleep; nothing can be recorded until one is.")
        }
        guard displayIndex < displays.count else {
            throw ToolError(
                message: "display must be 0…\(displays.count - 1) (got \(displayIndex)); "
                    + "\(displays.count) display\(displays.count == 1 ? " is" : "s are") "
                    + "shareable.")
        }
        return .display(displays[displayIndex].displayID)
    }
}
